28	public class SessionStoreBuilder<K, V> extends AbstractStoreBuilder<K, V, SessionStore<K, V>> {
29	
30	    private final SessionBytesStoreSupplier storeSupplier;
31	
32	    public SessionStoreBuilder(final SessionBytesStoreSupplier storeSupplier,
33	                               final Serde<K> keySerde,
34	                               final Serde<V> valueSerde,
35	                               final Time time) {
36	        super(Objects.requireNonNull(storeSupplier, "storeSupplier cannot be null").name(), keySerde, valueSerde, time);
