38	        this.storeSupplier = storeSupplier;
39	    }
40	
41	    @Override
42	    public SessionStore<K, V> build() {
43	        return new MeteredSessionStore<>(
44	            maybeWrapCaching(maybeWrapLogging(storeSupplier.get())),
45	            storeSupplier.metricsScope(),
46	            keySerde,
47	            valueSerde,
48	            time);
49	    }
50	
51	    private SessionStore<Bytes, byte[]> maybeWrapCaching(final SessionStore<Bytes, byte[]> inner) {
52	        if (!enableCaching) {
53	            return inner;
54	        }
55	        return new CachingSessionStore(inner, storeSupplier.segmentIntervalMs());
56	    }
