58	    private SessionStore<Bytes, byte[]> maybeWrapLogging(final SessionStore<Bytes, byte[]> inner) {
59	        if (!enableLogging) {
60	            return inner;
61	        }
62	        return new ChangeLoggingSessionBytesStore(inner);
63	    }
64	
65	    public long retentionPeriod() {
66	        return storeSupplier.retentionPeriod();
67	    }
